1	//! Chat input: a multi-line, Piton-highlighted editor on the left and a send
2	//! button on the right, in the body of the Code, +, and Spec tabs. Enter adds a
3	//! line; Ctrl/Cmd+Enter sends, or queues the prompt while the harness works.
4	//! Tab and Shift+Tab cycle the tabs and Esc takes focus out of the input.
5	
6	use std::rc::Rc;
7	use std::sync::Arc;
8	
9	use gpui_kit::Focusable as _;
10	use gpui_kit::assets::IconName;
11	use gpui_kit::component::button::{Button, ButtonVariants};
12	use gpui_kit::component::input::{
13	    CompletionProvider, Editor, EditorState, Enter, Escape, IndentInline, InputEvent,
14	    OutdentInline, Rope,
15	};
16	use gpui_kit::component::tab::{Tab, TabBar};
17	use gpui_kit::component::{ActiveTheme, Disableable};
18	use gpui_kit::prelude::FluentBuilder as _;
19	use gpui_kit::*;
20	use lsp_types::{CompletionContext, CompletionResponse};
21	
22	use crate::harness_mentions;
23	use crate::main_window::FocusChat;
24	use crate::piton_lsp::PitonSession;
25	use crate::piton_syntax;
26	use crate::project_directory::ProjectDirectory;
27	use crate::project_lsp::ProjectLsp;
28	
29	/// The input grows with its text up to this many rows, then scrolls.
30	const MAX_ROWS: usize = 12;
31	
32	/// Room the editor keeps free at the right of each line when soft wrapping.
33	const WRAP_RIGHT_MARGIN: Pixels = px(10.);
34	
35	#[cfg(target_os = "macos")]
36	const SEND_SHORTCUT: &str = "⌘Enter";
37	#[cfg(not(target_os = "macos"))]
38	const SEND_SHORTCUT: &str = "Ctrl+Enter";
39	
40	/// The tabs the input sits in, in the order Tab cycles them.
41	const TABS: [SendMode; 3] = [SendMode::Code, SendMode::Both, SendMode::Spec];
42	
43	/// The side of the square chain tab, half the height of the tabs.
44	const BOTH_TAB_SIZE: Pixels = px(16.);
45	
46	/// Index of the chain tab in `TABS`.
47	const BOTH_TAB: usize = 1;
48	
49	/// What a prompt is sent to work on: the selected tab.
50	#[derive(Clone, Copy, Debug, PartialEq)]
51	pub enum SendMode {
52	    Code,
53	    /// The code and the spec together.
54	    Both,
55	    Spec,
56	}
57	
58	impl SendMode {
59	    fn label(self) -> &'static str {
60	        match self {
61	            SendMode::Code => "Code",
62	            SendMode::Both => "Code and Spec",
63	            SendMode::Spec => "Spec",
64	        }
65	    }
66	
67	    fn id(self) -> &'static str {
68	        match self {
69	            SendMode::Code => "code-tab",
70	            SendMode::Both => "both-tab",
71	            SendMode::Spec => "spec-tab",
72	        }
73	    }
74	}
75	
76	/// Emitted with the input's text, and the mode it is sent in, when the user
77	/// sends it.
78	pub struct Submit {
79	    pub text: String,
80	    pub mode: SendMode,
81	}
82	
83	pub struct ChatInput {
84	    editor: Entity<EditorState>,
85	    /// The tab bar and its body, which Esc moves focus to: out of the input,
86	    /// but not onto nothing, where the window would hand it straight back.
87	    focus_handle: FocusHandle,
88	    /// Index into `TABS`.
89	    selected_tab: usize,
90	    lsp: Option<Arc<PitonSession>>,
91	    busy: bool,
92	    /// Width the editor's text was last laid out in, which decides where long
93	    /// lines soft wrap.
94	    text_width: Option<Pixels>,
95	    /// What the editor adds around its rows (padding and border) as last
96	    /// laid out, rounded to device pixels.
97	    chrome: Option<Pixels>,
98	    _subscriptions: Vec<Subscription>,
99	}
100	
101	impl EventEmitter<Submit> for ChatInput {}
102	
103	impl ChatInput {
104	    pub fn new(window: &mut Window, cx: &mut Context<Self>) -> Self {
105	        let editor = cx.new(|cx| {
106	            EditorState::new(window, cx)
107	                .language(piton_syntax::LANGUAGE_NAME)
108	                .line_number(false)
109	                .folding(false)
110	                .soft_wrap(true)
111	                // No empty rows below the last line: the input is sized to its
112	                // text, so any extra would be blank space, and it would leave
113	                // room for the editor to stay scrolled past the first line
114	                // after Enter grows the input.
115	                .scroll_beyond_last_line(Some(0))
116	                .placeholder(format!(
117	                    "Write a prompt… (/ for skills and commands, @ for agents, {SEND_SHORTCUT} to send)"
118	                ))
119	        });
120	        // Typing goes straight into the input, without clicking it first.
121	        editor.read(cx).focus_handle(cx).focus(window, cx);
122	
123	        let subscriptions = vec![
124	            cx.subscribe(&editor, |this, editor, event: &InputEvent, cx| {
125	                // An edit may be an accepted completion, whose import the
126	                // hidden anchor then takes on.
127	                if matches!(event, InputEvent::Change)
128	                    && let Some(lsp) = &this.lsp
129	                {
130	                    lsp.note_edit(&editor.read(cx).value());
131	                }
132	                // Re-render on every edit so the input can grow to fit its text.
133	                cx.notify();
134	            }),
135	            cx.observe_global_in::<ProjectLsp>(window, |this, _, cx| this.connect_lsp(cx)),
136	        ];
137	
138	        let mut this = Self {
139	            editor,
140	            focus_handle: cx.focus_handle(),
141	            selected_tab: 0,
142	            lsp: None,
143	            busy: false,
144	            text_width: None,
145	            chrome: None,
146	            _subscriptions: subscriptions,
147	        };
148	        this.connect_lsp(cx);
149	        this
150	    }
151	
152	    /// The project's `piton lsp` session, once it is running.
153	    pub fn lsp(&self) -> Option<Arc<PitonSession>> {
154	        self.lsp.clone()
155	    }
156	
157	    /// Moves keyboard focus into the input.
158	    pub fn focus(&mut self, window: &mut Window, cx: &mut Context<Self>) {
159	        self.editor.read(cx).focus_handle(cx).focus(window, cx);
160	    }
161	
162	    /// Inserts a harness mention at the cursor, after a space when the cursor
163	    /// follows other text, then moves focus into the input.
164	    pub fn insert_mention(&mut self, mention: &str, window: &mut Window, cx: &mut Context<Self>) {
165	        self.editor.update(cx, |editor, cx| {
166	            let value = editor.value();
167	            let follows_text = value
168	                .get(..editor.cursor())
169	                .and_then(|before| before.chars().next_back())
170	                .is_some_and(|c| !c.is_whitespace());
171	            let text = if follows_text {
172	                format!(" {mention}")
173	            } else {
174	                mention.to_string()
175	            };
176	            editor.insert(text, window, cx);
177	        });
178	        self.focus(window, cx);
179	    }
180	
181	    #[cfg(test)]
182	    pub fn value(&self, cx: &App) -> SharedString {
183	        self.editor.read(cx).value()
184	    }
185	
186	    #[cfg(test)]
187	    pub fn is_focused(&self, window: &Window, cx: &App) -> bool {
188	        self.editor.read(cx).focus_handle(cx).is_focused(window)
189	    }
190	
191	    /// Marks the harness as working; sending then queues the prompt.
192	    pub fn set_busy(&mut self, busy: bool, cx: &mut Context<Self>) {
193	        self.busy = busy;
194	        cx.notify();
195	    }
196	
197	    /// Points completions at the project's `piton lsp`, once it is running.
198	    /// Harness mentions complete without it.
199	    fn connect_lsp(&mut self, cx: &mut Context<Self>) {
200	        let client = ProjectLsp::get(cx);
201	        let connected = self.lsp.as_ref().map(|lsp| Arc::as_ptr(lsp.client()));
202	        if client.as_ref().map(Arc::as_ptr) == connected {
203	            return;
204	        }
205	        self.lsp = client.map(|client| Arc::new(PitonSession::new(client)));
206	        self.set_completions(self.lsp.clone(), cx);
207	    }
208	
209	    fn set_completions(&mut self, lsp: Option<Arc<PitonSession>>, cx: &mut Context<Self>) {
210	        let completions = Rc::new(PromptCompletions { lsp });
211	        self.editor.update(cx, |editor, _| {
212	            editor.lsp_mut().completion_provider = Some(completions)
213	        });
214	    }
215	
216	    fn submit(&mut self, window: &mut Window, cx: &mut Context<Self>) {
217	        let text = self.editor.read(cx).value().to_string();
218	        if text.is_empty() {
219	            return;
220	        }
221	        self.editor
222	            .update(cx, |editor, cx| editor.set_value("", window, cx));
223	        cx.emit(Submit {
224	            text,
225	            mode: TABS[self.selected_tab],
226	        });
227	    }
228	
229	    /// Selects a clicked tab and puts focus back in the input.
230	    fn select_tab(&mut self, ix: usize, window: &mut Window, cx: &mut Context<Self>) {
231	        self.selected_tab = ix;
232	        self.focus(window, cx);
233	        cx.notify();
234	    }
235	
236	    /// Moves `step` tabs along, wrapping around. An open completion menu
237	    /// keeps its own Tab and Shift+Tab.
238	    fn cycle_tab(&mut self, step: isize, cx: &mut Context<Self>) {
239	        if self.editor.read(cx).completion_menu_state().open {
240	            return;
241	        }
242	        cx.stop_propagation();
243	        let count = TABS.len() as isize;
244	        self.selected_tab = (self.selected_tab as isize + step).rem_euclid(count) as usize;
245	        cx.notify();
246	    }
247	
248	    /// Esc closes an open completion menu, and otherwise takes focus out of
249	    /// the input.
250	    fn escape(&mut self, window: &mut Window, cx: &mut Context<Self>) {
251	        if self.editor.read(cx).completion_menu_state().open {
252	            self.editor.update(cx, |editor, cx| {
253	                editor.route_overlay_action(Box::new(Escape), window, cx)
254	            });
255	        } else {
256	            self.focus_handle.focus(window, cx);
257	        }
258	    }
259	
260	    /// The rows `text` takes in the editor: one per line, plus one for every
261	    /// soft wrap, wrapped the way the editor wraps it.
262	    fn visual_rows(&self, text: &str, window: &Window, cx: &App) -> usize {
263	        let Some(wrap_width) = self.text_width.map(|width| width - WRAP_RIGHT_MARGIN) else {
264	            return text.split('\n').count();
265	        };
266	        let theme = cx.theme();
267	        let mut wrapper = window
268	            .text_system()
269	            .line_wrapper(font(theme.mono_font_family.clone()), theme.mono_font_size);
270	        text.split('\n')
271	            .map(|line| {
272	                1 + wrapper
273	                    .wrap_line(&[LineFragment::text(line)], wrap_width)
274	                    .count()
275	            })
276	            .sum()
277	    }
278	}
279	
280	impl Render for ChatInput {
281	    fn render(&mut self, window: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
282	        let text = self.editor.read(cx).value();
283	        let rows = self.visual_rows(&text, window, cx).clamp(1, MAX_ROWS);
284	        // Fit the text with the editor's own metrics: its laid-out line height
285	        // plus the padding and border around its rows. Until the editor has
286	        // painted, the border is estimated at a device pixel or more per side.
287	        let line_height = self
288	            .editor
289	            .read(cx)
290	            .line_height()
291	            .unwrap_or_else(|| window.line_height());
292	        let chrome = self.chrome.unwrap_or_else(|| {
293	            gpui_kit::component::Size::Medium.input_py() * 2.
294	                + ceil_to_device_pixel(px(1.), window) * 2.
295	        });
296	        let height = ceil_to_device_pixel(line_height * rows as f32 + chrome, window);
297	        let one_row = ceil_to_device_pixel(line_height + chrome, window);
298	        let empty = text.is_empty();
299	
300	        // Once the editor has painted, check how it was laid out: the width
301	        // its text wrapped in (a resized window wraps long lines differently)
302	        // and the padding and border around its rows. When either changed,
303	        // the input re-fits.
304	        let this = cx.entity().downgrade();
305	        let editor = self.editor.clone();
306	        let track_layout = canvas(
307	            |_, _, _| {},
308	            move |bounds, _, _, cx| {
309	                let Some(text_bounds) = editor.read(cx).text_bounds() else {
310	                    return;
311	                };
312	                let width = text_bounds.size.width;
313	                let chrome = bounds.size.height - text_bounds.size.height;
314	                this.update(cx, |this, cx| {
315	                    let chrome_changed = this
316	                        .chrome
317	                        .is_none_or(|old| (old - chrome).abs() > px(0.01));
318	                    if this.text_width != Some(width) || chrome_changed {
319	                        this.text_width = Some(width);
320	                        if chrome_changed {
321	                            this.chrome = Some(chrome);
322	                        }
323	                        cx.notify();
324	                    }
325	                })
326	                .ok();
327	            },
328	        )
329	        .absolute()
330	        .size_full();
331	
332	        // Code and Spec are full tabs side by side, each its own bar, and the
333	        // chain is a small square button laid over the seam between them: broken
334	        // until selected, then joined. Selecting it selects both tabs and covers
335	        // the seam, so they read as one tab.
336	        let selected = self.selected_tab;
337	        let unified = selected == BOTH_TAB;
338	        let chat_input = cx.entity().downgrade();
339	        let full_tab = |ix: usize| {
340	            let chat_input = chat_input.clone();
341	            let bar = TabBar::new(TABS[ix].id())
