498	/// Completions for the chat input: harness mentions after `/` or `@`, and
499	/// Piton from `piton lsp`, when it is running, everywhere else.
500	struct PromptCompletions {
501	    lsp: Option<Arc<PitonSession>>,
502	}
503	
504	impl CompletionProvider for PromptCompletions {
505	    fn completions(
506	        &self,
507	        text: &Rope,
508	        offset: usize,
509	        _: CompletionContext,
510	        _: &mut Window,
511	        cx: &mut App,
512	    ) -> Task<Result<CompletionResponse>> {
513	        let lsp = self.lsp.clone();
514	        let prompt = text.to_string();
515	        let project_dir = ProjectDirectory::get(cx);
516	        cx.background_spawn(async move {
517	            if harness_mentions::mention_at(&prompt, offset).is_some() {
518	                let invocables = harness_mentions::discover(project_dir.as_deref());
519	                let items = harness_mentions::complete(&prompt, offset, &invocables);
520	                return Ok(CompletionResponse::Array(items.unwrap_or_default()));
521	            }
522	            // A slash or hyphen only triggers completion inside a mention.
523	            let typed = prompt
524	                .get(..offset)
525	                .and_then(|before| before.chars().next_back());
526	            match lsp {
527	                Some(lsp) if !matches!(typed, Some('/' | '-')) => lsp.complete(&prompt, offset),
528	                _ => Ok(CompletionResponse::Array(Vec::new())),
529	            }
530	        })
531	    }
532	
533	    fn is_completion_trigger(&self, _: usize, new_text: &str, _: &mut App) -> bool {
534	        new_text.chars().last().is_some_and(|c| {
535	            c.is_alphanumeric() || matches!(c, '{' | '.' | '$' | '@' | ':' | '_' | '/' | '-')
536	        })
537	    }
538	}
