917	        scroll_y: gpui_kit::Pixels,
918	        cursor_top: gpui_kit::Pixels,
919	        cursor_bottom: gpui_kit::Pixels,
920	    }
921	
922	    /// Presses Enter in the input at the bottom of the window, `presses`
923	    /// times, and records every frame drawn after each press, the way the
924	    /// window draws them: only what the press invalidated, with no forced
925	    /// refresh in between.
926	    async fn frames_after_enter(
927	        presses: usize,
928	        scale_factor: f32,
929	        cx: &mut TestAppContext,
930	    ) -> (gpui_kit::Pixels, Vec<Vec<Frame>>) {
931	        cx.update(|cx| {
932	            gpui_kit::init(cx);
933	            piton_syntax::init();
934	            ProjectDirectory::init(cx);
935	        });
936	        let mut chat_input = None;
937	        let painted = Rc::new(Cell::new(gpui_kit::px(0.)));
938	        let window = cx.add_window(|window, cx| {
939	            let input = cx.new(|cx| ChatInput::new(window, cx));
940	            chat_input = Some(input.clone());
941	            let painted_scroll_y = painted.clone();
942	            let view = cx.new(|_| Probed {
943	                input,
944	                painted_scroll_y,
945	            });
946	            Root::new(view, window, cx)
947	        });
948	        let chat_input = chat_input.unwrap();
949	        let editor = chat_input.read_with(cx, |input, _| input.editor.clone());
950	        let handle = window.into();
951	        // Most displays are not 2x: at other scales the rows are a fraction
952	        // of a pixel off the device grid.
953	        cx.simulate_window_scale_factor_change(handle, scale_factor);
954	        cx.wait_for(handle, TIMEOUT, |_, cx| {
955	            editor.read(cx).line_height().is_some()
956	        })
957	        .await;
958	
959	        let record = |window: &mut Window, cx: &mut gpui_kit::App| {
960	            window.draw(cx).clear(cx);
961	            let bounds = window.find("prompt-editor").bounds();
962	            let editor = editor.read(cx);
963	            let scroll_y = editor.scroll_offset().y;
964	            // The cursor is laid out in window coordinates, before scrolling.
965	            let (cursor, _) = editor.cursor_layout().unwrap();
966	            let painted_scroll_y = painted.get();
967	            Frame {
968	                rows: editor.value().split('\n').count(),
969	                top: bounds.top(),
970	                bottom: bounds.bottom(),
971	                height: bounds.size.height,
972	                painted_scroll_y,
973	                scroll_y,
974	                cursor_top: cursor.top() + painted_scroll_y,
975	                cursor_bottom: cursor.bottom() + painted_scroll_y,
976	            }
977	        };
978	
979	        cx.update_window(handle, |_, window, cx| {
980	            editor.read(cx).focus_handle(cx).focus(window, cx);
981	            window.render_frame(cx);
982	            window.render_frame(cx);
983	            window.input("x", cx);
984	        })
985	        .unwrap();
986	        let line_height = editor.read_with(cx, |editor, _| editor.line_height().unwrap());
987	
988	        let mut presses_frames = vec![];
989	        for _ in 0..presses {
990	            let frames = cx
991	                .update_window(handle, |_, window, cx| {
992	                    let before = record(window, cx);
993	                    window.dispatch_keystroke(gpui_kit::Keystroke::parse("enter").unwrap(), cx);
994	                    let mut frames = vec![before];
995	                    for _ in 0..6 {
996	                        frames.push(record(window, cx));
997	                    }
998	                    frames
999	                })
1000	                .unwrap();
1001	            cx.run_until_parked();
1002	            presses_frames.push(frames);
1003	        }
1004	        (line_height, presses_frames)
1005	    }
1006	
1007	    /// Enter grows the input by one row in the very next frame, and it stays
1008	    /// put from then on: the bottom edge never moves, the first line never
1009	    /// scrolls out of view, and the cursor is always inside the input.
1010	    async fn assert_enter_grows_without_flicker(scale_factor: f32, cx: &mut TestAppContext) {
1011	        let (line_height, presses) = frames_after_enter(MAX_ROWS + 3, scale_factor, cx).await;
1012	        let bottom = presses[0][0].bottom;
1013	        let one_row = presses[0][0].height;
1014	        for (press, frames) in presses.iter().enumerate() {
1015	            let rows = frames.last().unwrap().rows;
1016	            let expected = one_row + line_height * (rows.min(MAX_ROWS) - 1) as f32;
1017	            for (ix, frame) in frames.iter().enumerate().skip(1) {
1018	                let context = format!(
1019	                    "at {scale_factor}x, line height {line_height:?}, press {press}, frame {ix} of {frames:#?}"
1020	                );
1021	                assert!(
1022	                    (frame.height - expected).abs() <= gpui_kit::px(0.5),
1023	                    "height is not {expected:?} rows: {context}"
1024	                );
1025	                assert!(
1026	                    (frame.bottom - bottom).abs() <= gpui_kit::px(0.5),
1027	                    "the bottom edge moved from {bottom:?}: {context}"
1028	                );
1029	                if rows <= MAX_ROWS {
1030	                    assert!(
1031	                        frame.painted_scroll_y.abs() <= gpui_kit::px(0.5),
1032	                        "painted scrolled although everything fits: {context}"
1033	                    );
1034	                } else {
1035	                    assert!(
1036	                        (frame.painted_scroll_y - frames.last().unwrap().painted_scroll_y).abs()
1037	                            <= gpui_kit::px(0.5),
1038	                        "scroll did not settle in the first frame: {context}"
1039	                    );
1040	                }
1041	                assert!(
1042	                    frame.cursor_top >= frame.top - gpui_kit::px(0.5)
1043	                        && frame.cursor_bottom <= frame.bottom + gpui_kit::px(0.5),
1044	                    "the cursor is outside the input: {context}"
1045	                );
1046	            }
1047	        }
1048	    }
1049	
1050	    #[gpui_kit::test]
1051	    async fn enter_grows_the_input_without_flicker_at_1x(cx: &mut TestAppContext) {
1052	        assert_enter_grows_without_flicker(1.0, cx).await;
1053	    }
1054	
1055	    #[gpui_kit::test]
1056	    async fn enter_grows_the_input_without_flicker_at_1_25x(cx: &mut TestAppContext) {
1057	        assert_enter_grows_without_flicker(1.25, cx).await;
1058	    }
1059	
1060	    #[gpui_kit::test]
1061	    async fn enter_grows_the_input_without_flicker_at_1_5x(cx: &mut TestAppContext) {
1062	        assert_enter_grows_without_flicker(1.5, cx).await;
1063	    }
1064	
1065	    #[gpui_kit::test]
1066	    async fn enter_grows_the_input_without_flicker_at_1_75x(cx: &mut TestAppContext) {
1067	        assert_enter_grows_without_flicker(1.75, cx).await;
1068	    }
1069	
1070	    #[gpui_kit::test]
1071	    async fn enter_grows_the_input_without_flicker_at_2x(cx: &mut TestAppContext) {
1072	        assert_enter_grows_without_flicker(2.0, cx).await;
1073	    }
1074	
1075	    /// The input grows a row for each line and for each soft wrap of a long
1076	    /// line, and shrinks back when the text goes.
1077	    #[gpui_kit::test]
1078	    async fn input_grows_and_shrinks_with_its_text(cx: &mut TestAppContext) {
1079	        cx.update(|cx| {
1080	            gpui_kit::init(cx);
1081	            piton_syntax::init();
1082	            ProjectDirectory::init(cx);
1083	        });
1084	        let mut chat_input = None;
1085	        let window = cx.add_window(|window, cx| {
1086	            let input = cx.new(|cx| ChatInput::new(window, cx));
1087	            chat_input = Some(input.clone());
1088	            Root::new(input, window, cx)
1089	        });
1090	        let chat_input = chat_input.unwrap();
1091	        let editor = chat_input.read_with(cx, |input, _| input.editor.clone());
1092	        let handle = window.into();
1093	        cx.wait_for(handle, TIMEOUT, |window, _| {
1094	            window.try_find("prompt-editor").is_some()
1095	        })
1096	        .await;
1097	
1098	        let set_text = |text: String, cx: &mut TestAppContext| {
1099	            cx.update_window(handle, |_, window, cx| {
1100	                editor.update(cx, |editor, cx| editor.set_value(text, window, cx));
1101	                // Lay out the text, then fit the input to it.
1102	                for _ in 0..3 {
1103	                    window.render_frame(cx);
1104	                }
1105	                let line_height = editor.read(cx).line_height().unwrap();
1106	                let height = window.find("prompt-editor").bounds().size.height;
1107	                (height, line_height)
1108	            })
1109	            .unwrap()
1110	        };
1111	
1112	        let (one_row, line_height) = set_text(String::new(), cx);
1113	
1114	        let (three_lines, _) = set_text("one\ntwo\nthree".into(), cx);
1115	        assert!(
1116	            (three_lines - one_row - line_height * 2.).abs() <= gpui_kit::px(1.),
1117	            "three lines: {three_lines:?}, one row: {one_row:?}, line height: {line_height:?}"
1118	        );
1119	
1120	        let (wrapped, _) = set_text("a long line that has to wrap ".repeat(40), cx);
1121	        assert!(
1122	            wrapped >= one_row + line_height * 2.,
1123	            "one long line did not grow the input: {wrapped:?} vs one row {one_row:?}"
1124	        );
1125	        let editor_width = cx
1126	            .update_window(handle, |_, window, _| {
1127	                window.find("prompt-editor").bounds().size.width
1128	            })
1129	            .unwrap();
1130	        assert!(
1131	            editor_width
1132	                <= cx
1133	                    .update_window(handle, |_, window, _| window.viewport_size().width)
1134	                    .unwrap(),
1135	            "the input got wider than the window instead of wrapping"
1136	        );
1137	
1138	        let (cleared, _) = set_text(String::new(), cx);
1139	        assert!(
1140	            (cleared - one_row).abs() <= gpui_kit::px(1.),
1141	            "cleared input did not shrink back: {cleared:?} vs {one_row:?}"
1142	        );
1143	    }
1144	}
