        })
        .await;

        cx.update_window(handle, |_, window, cx| window.input("hi", cx))
            .unwrap();
        cx.run_until_parked();
        let presses = [
            ("tab", 1),
            ("tab", 2),
            ("tab", 0),
            ("tab", 1),
